import React, { useEffect, useState } from 'react';
import api from '../utils/api';

const ChartComponent = () => {
    const [data, setData] = useState({ invoices: [], flights: [] });
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const result = await api.getData();
                setData(result.data || { invoices: [], flights: [] });  // Ensure there are defaults

                // Log data to understand its structure
                console.log("Complete Data Received:", result.data);
                console.log("Invoices Data:", result.data.invoices);
                console.log("Logged-Flights Data:", result.data.loggedFlights);

                // If there's at least one invoice and one flight, log their structures
                if (result.data.invoices.length > 0) {
                    console.log("Sample Invoice:", result.data.invoices[0]);
                    console.log("Keys and Sample Values of an Invoice:", Object.entries(result.data.invoices[0]).map(([key, value]) => `${key}: ${value}`));
                }
                if (result.data.loggedFlights.length > 0) {
                    console.log("Sample Logged Flight:", result.data.loggedFlights[0]);
                    console.log("Keys and Sample Values of a Logged Flight:", Object.entries(result.data.loggedFlights[0]).map(([key, value]) => `${key}: ${value}`));
                }
            } catch (error) {
                console.error('Error fetching data:', error);
                setError('Error fetching data.');
            }
        };

        fetchData();
    }, []);

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div>
            <h1>Data Overview</h1>
            <p>Check the console for detailed data logs.</p>
        </div>
    );
};

export default ChartComponent;
